class ConCacheEta(EstrategiaEta):
    """Solo guarda respuestas EXITOSAS (si la interna falla, nada se guarda)."""

    def __init__(self, interna: EstrategiaEta):
        self._interna, self._cache = interna, {}

    def estimar(self, pos, paradero):
        clave = (round(pos.lat, 3), round(pos.lon, 3), paradero)
        if clave not in self._cache:
            self._cache[clave] = self._interna.estimar(pos, paradero)
        return self._cache[clave]

class ConRespaldo(EstrategiaEta):
    """Si la principal agota sus reintentos, usa la estrategia de respaldo."""

    def __init__(self, principal: EstrategiaEta, respaldo: EstrategiaEta):
        self._principal, self._respaldo = principal, respaldo

    def estimar(self, pos, paradero):
        try:
            return self._principal.estimar(pos, paradero)
        except TimeoutError:
            return self._respaldo.estimar(pos, paradero)

class ProveedorMapas(ABC):
    @abstractmethod
    def tiempo_de_recorrido(self, origen, destino) -> int:
        """Segundos de recorrido."""

class EtaPorMapas(EstrategiaEta):
    def __init__(self, mapas: ProveedorMapas):
        self._mapas = mapas

    def estimar(self, pos, paradero):
        return round(self._mapas.tiempo_de_recorrido((pos.lat, pos.lon), paradero) / 60)

class ConReintentosEta(EstrategiaEta):
    def __init__(self, interna: EstrategiaEta, intentos: int = 3):
        self._interna, self._intentos = interna, intentos

    def estimar(self, pos, paradero):
        for i in range(self._intentos):
            try:
                return self._interna.estimar(pos, paradero)
            except TimeoutError:
                if i == self._intentos - 1:
                    raise

# El constructor de ServicioEta ya trae GPS, mapas y LLM simulados (rutasit.externos).
# Viaje(id, placa, operador, estado='PROGRAMADO') esta en rutasit.servicio.
    def consultar_eta(self, viaje, paradero, algoritmo="MAPAS"):
        viaje.verificar_eta()
        gps = self.fabrica_gps.crear(viaje.operador)
        estrategia = self.fabrica_eta.crear(algoritmo)
        pos = gps.leer(viaje.placa)
        if pos is None:
            self.publicador.publicar("sin_senal", {"id": viaje.id})
            return Estimacion(0, False)
        viaje.posiciones.append(pos)
        minutos = estrategia.estimar(pos, paradero)
        datos = {"id": viaje.id, "paradero": paradero, "minutos": minutos}
        self.publicador.publicar("eta_calculado", datos)
        if minutos > LIMITE_RETRASO_MIN:
            self.publicador.publicar("retraso_detectado", datos)
        return Estimacion(minutos, True)

class Programado(EstadoViaje):
    nombre = "PROGRAMADO"

    def iniciar(self, viaje): viaje.cambiar_a(EnRuta())
    def verificar_eta(self, viaje): raise ValueError("El viaje aun no inicia")

class EnRuta(EstadoViaje):
    nombre = "EN_RUTA"

    def marcar_desviado(self, viaje): viaje.cambiar_a(Desviado())
    def marcar_detenido(self, viaje): viaje.cambiar_a(Detenido())
    def finalizar(self, viaje): viaje.cambiar_a(Finalizado())
    def verificar_eta(self, viaje): return None

class Finalizado(EstadoViaje):
    nombre = "FINALIZADO"

    def verificar_eta(self, viaje): raise ValueError("El viaje ya finalizo")

